package org.apache.commons.math3.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.FieldElement;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Complex_abs_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testAbs_NaN() {
        Complex c = new Complex(Double.NaN, 1.0);
        assertEquals(Double.NaN, c.abs(), 0.0);
    }

    @Test
    public void testAbs_Infinite() {
        Complex c = new Complex(Double.POSITIVE_INFINITY, 1.0);
        assertEquals(Double.POSITIVE_INFINITY, c.abs(), 0.0);
    }

    @Test
    public void testAbs_ZeroRealImaginary() {
        Complex c = new Complex(0.0, 0.0);
        assertEquals(0.0, c.abs(), EPSILON);
    }

    @Test
    public void testAbs_RealOnly() {
        Complex c = new Complex(5.0, 0.0);
        assertEquals(5.0, c.abs(), EPSILON);

        Complex cNeg = new Complex(-5.0, 0.0);
        assertEquals(5.0, cNeg.abs(), EPSILON);
    }

    @Test
    public void testAbs_ImaginaryOnly() {
        Complex c = new Complex(0.0, 5.0);
        assertEquals(5.0, c.abs(), EPSILON);

        Complex cNeg = new Complex(0.0, -5.0);
        assertEquals(5.0, cNeg.abs(), EPSILON);
    }

    @Test
    public void testAbs_RealDominant() {
        // |real| > |imaginary|
        // Case: real = 4, imag = 3 -> abs = 5
        Complex c = new Complex(4.0, 3.0);
        assertEquals(5.0, c.abs(), EPSILON);

        // Case: real = -4, imag = -3 -> abs = 5
        Complex c2 = new Complex(-4.0, -3.0);
        assertEquals(5.0, c2.abs(), EPSILON);
    }

    @Test
    public void testAbs_ImaginaryDominant() {
        // |imaginary| > |real|
        // Case: real = 3, imag = 4 -> abs = 5
        Complex c = new Complex(3.0, 4.0);
        assertEquals(5.0, c.abs(), EPSILON);

        // Case: real = -3, imag = 4 -> abs = 5
        Complex c2 = new Complex(-3.0, 4.0);
        assertEquals(5.0, c2.abs(), EPSILON);
    }

    @Test
    public void testAbs_SmallRealLargeImaginary() {
        // Testing the branch: if (FastMath.abs(real) < FastMath.abs(imaginary)) 
        // and the q calculation
        Complex c = new Complex(1e-10, 1.0);
        assertEquals(Math.sqrt(1.0 + 1e-20), c.abs(), EPSILON);
    }

    @Test
    public void testAbs_SmallImaginaryLargeReal() {
        // Testing the branch: else (real dominant)
        // and the q calculation
        Complex c = new Complex(1.0, 1e-10);
        assertEquals(Math.sqrt(1.0 + 1e-20), c.abs(), EPSILON);
    }

    @Test
    public void testAbs_ExtremeValues() {
        // Large values to check stability
        Complex c = new Complex(1e150, 1e150);
        // sqrt(2) * 1e150
        assertEquals(Math.sqrt(2.0) * 1e150, c.abs(), 1e140);
    }
}
